typedef enum { UNIT_METRE, UNIT_KILOMETRE, UNIT_FOOT } unit_t;

typedef struct { double amount; unit_t unit; } quantity_t;

quantity_t metres(double m) { return (quantity_t){ m, UNIT_METRE }; }

/* one table owns the factors; one function owns the dimension check */
bool   quantity_add(quantity_t a, quantity_t b, quantity_t *out);
double quantity_in(quantity_t q, unit_t target);
